WITH cleaned AS (SELECT *, GREATEST(temp_c, pressure) AS greatest_temp_c_pressure FROM device_readings WHERE humidity BETWEEN 40 AND 68), enriched AS (SELECT id, reading_ts, pressure, status_bits, firmware, greatest_temp_c_pressure, STDDEV_SAMP(temp_c) OVER (PARTITION BY DATE_TRUNC('YEAR', reading_ts)) AS reading_ts_period_stddev_samp_temp_c, AVG(status_bits) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS status_bits_avg_2h FROM cleaned), cleaned_device_readings AS (SELECT id, reading_ts, status_bits, firmware, greatest_temp_c_pressure, reading_ts_period_stddev_samp_temp_c, status_bits_avg_2h, reading_ts_period_stddev_samp_temp_c + status_bits_avg_2h AS reading_ts_period_stddev_samp_temp_c_plus_status_bits_avg_2h FROM enriched WHERE reading_ts > DATE '2025-09-01'), valid AS (SELECT id, status_bits, firmware, greatest_temp_c_pressure, reading_ts_period_stddev_samp_temp_c, status_bits_avg_2h, ROUND(reading_ts_period_stddev_samp_temp_c, 0) AS reading_ts_period_stddev_samp_temp_c_rounded FROM cleaned_device_readings WHERE status_bits < 10), valid_device_readings AS (SELECT *, ROUND(greatest_temp_c_pressure * 1.15, 2) AS greatest_temp_c_pressure_scaled, TRIM(firmware) AS clean_firmware FROM valid WHERE reading_ts_period_stddev_samp_temp_c = 30) SELECT id, status_bits, reading_ts_period_stddev_samp_temp_c, reading_ts_period_stddev_samp_temp_c_rounded, greatest_temp_c_pressure_scaled FROM valid_device_readings ORDER BY id DESC NULLS LAST, reading_ts_period_stddev_samp_temp_c;
